interface ComplianceContextType {
  tasks: GRCTask[];
  controls: GRCControl[];
  policies: Policy[];
  documents: GRCDocument[];
  checks: AutomatedCheck[];
  milestones: Milestone[];
  integrations: Integration[];
  chatMessages: ChatMessage[];

  addTask: (t: Omit<GRCTask, 'id' | 'createdAt' | 'updatedAt'>) => GRCTask;
  updateTask: (id: string, t: Partial<GRCTask>) => void;
  deleteTask: (id: string) => void;

  addControl: (c: Omit<GRCControl, 'id' | 'createdAt' | 'updatedAt'>) => void;
  updateControl: (id: string, c: Partial<GRCControl>) => void;
  deleteControl: (id: string) => void;

  addPolicy: (p: Omit<Policy, 'id' | 'createdAt' | 'updatedAt'>) => void;
  updatePolicy: (id: string, p: Partial<Policy>) => void;
  deletePolicy: (id: string) => void;

  addDocument: (d: Omit<GRCDocument, 'id'>) => void;
  deleteDocument: (id: string) => void;

  addMilestone: (m: Omit<Milestone, 'id'>) => void;
  updateMilestone: (id: string, m: Partial<Milestone>) => void;

  updateIntegration: (id: string, d: Partial<Integration>) => void;

  addChatMessage: (m: Omit<ChatMessage, 'id' | 'timestamp'>) => void;
  clearChat: () => void;
}

