function loadFromStorage<T>(key: string, fallback: T): T {
  try { const d = localStorage.getItem(key); return d ? JSON.parse(d) : fallback; } catch { return fallback; }
}

export function ComplianceProvider({ children }: { children: ReactNode }) {
  const [tasks, setTasks] = useState<GRCTask[]>(() => loadFromStorage('grc-tasks', SEED_TASKS));
  const [controls, setControls] = useState<GRCControl[]>([]);
  const [controlsLoaded, setControlsLoaded] = useState(false);
  const [policies, setPolicies] = useState<Policy[]>(() => loadFromStorage('grc-policies', SEED_POLICIES));
  const [documents, setDocuments] = useState<GRCDocument[]>(() => loadFromStorage('grc-documents', SEED_DOCUMENTS));
  const [checks, setChecks] = useState<AutomatedCheck[]>(() => loadFromStorage('grc-checks', SEED_CHECKS));
  const [milestones, setMilestones] = useState<Milestone[]>(() => loadFromStorage('grc-milestones', SEED_MILESTONES));
  const [integrations, setIntegrations] = useState<Integration[]>(() => loadFromStorage('grc-integrations', SEED_INTEGRATIONS));
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([]);

  useEffect(() => { localStorage.setItem('grc-tasks', JSON.stringify(tasks)); }, [tasks]);
  useEffect(() => {
    apiFetch('/api/controls')
      .then(res => res.ok ? res.json() : Promise.reject(new Error('Failed to load controls')))
      .then((data: GRCControl[]) => {
        setControls(data);
        setControlsLoaded(true);
      })
      .catch(() => {
        setControls(loadFromStorage('grc-controls', SEED_CONTROLS));
        setControlsLoaded(true);
      });
  }, []);
  useEffect(() => { if (controlsLoaded) localStorage.setItem('grc-controls', JSON.stringify(controls)); }, [controls, controlsLoaded]);
  useEffect(() => { localStorage.setItem('grc-policies', JSON.stringify(policies)); }, [policies]);
  useEffect(() => { localStorage.setItem('grc-documents', JSON.stringify(documents)); }, [documents]);
  useEffect(() => { localStorage.setItem('grc-checks', JSON.stringify(checks)); }, [checks]);
  useEffect(() => { localStorage.setItem('grc-milestones', JSON.stringify(milestones)); }, [milestones]);
  useEffect(() => { localStorage.setItem('grc-integrations', JSON.stringify(integrations)); }, [integrations]);

  const addTask = useCallback((d: Omit<GRCTask, 'id' | 'createdAt' | 'updatedAt'>) => {
    const now = new Date().toISOString();
    const created = { ...d, id: genId(), createdAt: now, updatedAt: now } as GRCTask;
    setTasks(prev => [created, ...prev]);
    return created;
  }, []);
  const updateTask = useCallback((id: string, d: Partial<GRCTask>) => setTasks(prev => prev.map(t => t.id === id ? { ...t, ...d, updatedAt: new Date().toISOString() } : t)), []);
  const deleteTask = useCallback((id: string) => setTasks(prev => prev.filter(t => t.id !== id)), []);

  const addControl = useCallback(async (d: Omit<GRCControl, 'id' | 'createdAt' | 'updatedAt'>) => {
    try {
      const res = await apiFetch('/api/controls', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(d),
      });
      if (res.ok) {
        const created = await res.json() as GRCControl;
        setControls(prev => [created, ...prev]);
        return;
      }
    } catch { /* fallback below */ }
    const now = new Date().toISOString();
    setControls(prev => [{ ...d, id: genId(), createdAt: now, updatedAt: now } as GRCControl, ...prev]);
  }, []);
  const updateControl = useCallback(async (id: string, d: Partial<GRCControl>) => {
    try {
      const res = await apiFetch(`/api/controls/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(d),
      });
      if (res.ok) {
        const updated = await res.json() as GRCControl;
        setControls(prev => prev.map(c => c.id === id ? updated : c));
        return;
      }
    } catch { /* fallback below */ }
    setControls(prev => prev.map(c => c.id === id ? { ...c, ...d, updatedAt: new Date().toISOString() } : c));
  }, []);
  const deleteControl = useCallback(async (id: string) => {
    try {
      const res = await apiFetch(`/api/controls/${id}`, { method: 'DELETE' });
      if (res.ok || res.status === 204) {
        setControls(prev => prev.filter(c => c.id !== id));
        return;
      }
    } catch { /* fallback below */ }
    setControls(prev => prev.filter(c => c.id !== id));
  }, []);

  const addPolicy = useCallback((d: Omit<Policy, 'id' | 'createdAt' | 'updatedAt'>) => {
    const now = new Date().toISOString();
    setPolicies(prev => [{ ...d, id: genId(), createdAt: now, updatedAt: now } as Policy, ...prev]);
  }, []);
  const updatePolicy = useCallback((id: string, d: Partial<Policy>) => setPolicies(prev => prev.map(p => p.id === id ? { ...p, ...d, updatedAt: new Date().toISOString() } : p)), []);
  const deletePolicy = useCallback((id: string) => setPolicies(prev => prev.filter(p => p.id !== id)), []);

  const addDocument = useCallback((d: Omit<GRCDocument, 'id'>) => setDocuments(prev => [{ ...d, id: genId() } as GRCDocument, ...prev]), []);
  const deleteDocument = useCallback((id: string) => setDocuments(prev => prev.filter(d => d.id !== id)), []);

  const addMilestone = useCallback((d: Omit<Milestone, 'id'>) => setMilestones(prev => [{ ...d, id: genId() } as Milestone, ...prev]), []);
  const updateMilestone = useCallback((id: string, d: Partial<Milestone>) => setMilestones(prev => prev.map(m => m.id === id ? { ...m, ...d } : m)), []);

  const updateIntegration = useCallback((id: string, d: Partial<Integration>) => setIntegrations(prev => prev.map(i => i.id === id ? { ...i, ...d } : i)), []);

  const addChatMessage = useCallback((d: Omit<ChatMessage, 'id' | 'timestamp'>) => {
    setChatMessages(prev => [...prev, { ...d, id: genId(), timestamp: new Date().toISOString() } as ChatMessage]);
  }, []);
  const clearChat = useCallback(() => setChatMessages([]), []);

  return (
    <ComplianceContext.Provider value={{
      tasks, controls, policies, documents, checks, milestones, integrations, chatMessages,
      addTask, updateTask, deleteTask,
      addControl, updateControl, deleteControl,
      addPolicy, updatePolicy, deletePolicy,
      addDocument, deleteDocument,
      addMilestone, updateMilestone,
      updateIntegration,
      addChatMessage, clearChat,
    }}>
      {children}
    </ComplianceContext.Provider>
  );
}

export function useCompliance() {
  const ctx = useContext(ComplianceContext);
  if (!ctx) throw new Error('useCompliance must be used within ComplianceProvider');
  return ctx;
}
